// Get current files from Google Drive
const driveFiles = $('Search files and folders').all();

// Get files currently registered in Supabase
const dbFiles = $('Get many rows').all();

// Create lookup of files stored in Supabase
const dbMap = new Map();

for (const item of dbFiles) {
  const file = item.json;

  // Ignore the empty item produced by "Always Output Data"
  if (!file || !file.drive_file_id) continue;

  dbMap.set(file.drive_file_id, file);
}

// Keep track of files currently in Google Drive
const driveIds = new Set();

const results = [];

// Check Google Drive files
for (const item of driveFiles) {
  const file = item.json;

  const driveId = file.id;
  const fileName = file.name;
  const modifiedTime = file.modifiedTime;

  if (!driveId) continue;

  driveIds.add(driveId);

  const existing = dbMap.get(driveId);

  // NEW FILE
  if (!existing) {
    results.push({
      json: {
        action: 'NEW',
        drive_file_id: driveId,
        file_name: fileName,
        mime_type: file.mimeType || null,
        modified_time: modifiedTime || null
      }
    });

    continue;
  }

  // EXISTING FILE — check modification
  const oldTime = existing.modified_time
    ? new Date(existing.modified_time).getTime()
    : null;

  const newTime = modifiedTime
    ? new Date(modifiedTime).getTime()
    : null;

  if (oldTime !== newTime) {
    results.push({
      json: {
        action: 'MODIFIED',
        drive_file_id: driveId,
        file_name: fileName,
        mime_type: file.mimeType || null,
        modified_time: modifiedTime || null,
        previous_modified_time: existing.modified_time || null
      }
    });
  } else {
    results.push({
      json: {
        action: 'UNCHANGED',
        drive_file_id: driveId,
        file_name: fileName
      }
    });
  }
}

// DELETED FILES
for (const [driveId, dbFile] of dbMap.entries()) {
  if (!driveIds.has(driveId)) {
    results.push({
      json: {
        action: 'DELETED',
        drive_file_id: driveId,
        file_name: dbFile.file_name
      }
    });
  }
}

return results;
